class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        ans = []
        colors = [0] * n
        count = 0

        for i, color in queries:
            if colors[i] != 0:
                if i > 0 and colors[i] == colors[i - 1]:
                    count -= 1
                if i < n - 1 and colors[i] == colors[i + 1]:
                    count -= 1

            colors[i] = color

            if i > 0 and colors[i] == colors[i - 1]:
                count += 1
            if i < n - 1 and colors[i] == colors[i + 1]:
                count += 1

            ans.append(count)

        return ans

